import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long k = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        long previous = 0;
        for (int i = 0; i < n; i++) {
            if (i > 0 && a[i] == a[i - 1]) continue; // duplicates take no extra place
            long gap = a[i] - previous - 1;
            if (k <= gap) {
                System.out.println(previous + k);
                return;
            }
            k -= gap;
            previous = a[i];
        }
        System.out.println(previous + k);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"sort"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n, k := int(nextInt()), nextInt()
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	sort.Slice(a, func(i, j int) bool { return a[i] < a[j] })
	var previous int64
	for i, v := range a {
		if i > 0 && v == a[i-1] {
			continue // duplicates take no extra place
		}
		gap := v - previous - 1
		if k <= gap {
			w.WriteString(strconv.FormatInt(previous+k, 10) + "\n")
			return
		}
		k -= gap
		previous = v
	}
	w.WriteString(strconv.FormatInt(previous+k, 10) + "\n")
}
